(function () {
    'use strict';
    const R = window.RackStudio, txt = v => String(v ?? 'Belirtilmedi');
    function grid(headers, rows, widths) { return { table: { headerRows: 1, widths: widths || headers.map(() => '*'), body: [headers.map(text => ({ text, bold: true, fillColor: '#eaf0f3' })), ...(rows.length ? rows : [[...headers.map(() => '—')]])].map(row => row.map(v => typeof v === 'object' ? v : { text: txt(v) })) }, layout: 'lightHorizontalLines', margin: [0, 6, 0, 10], fontSize: 7 }; }
    function definition(model, options = {}) {
        const doc = model.document, bom = R.BOM.build(model, options.bom), content = [{ text: options.company || doc.metadata.customer || 'Rack Studio', style: 'title' }, { text: doc.metadata.name || 'Adsız proje', style: 'heading' }, { text: `Proje: ${doc.projectId}\nRevizyon: ${doc.revision} · ${model.source.name}\nHazırlayan: ${doc.metadata.owner || 'Belirtilmedi'}\n${model.createdAt}\nTeknik durum: ${model.technicalComplete ? 'Tamamlandı' : 'Açık işler var'} · Teslim kabulü ayrı kayıttır.`, margin: [0, 0, 0, 12] }];
        for (const r of doc.topology.racks) for(const face of ['front', ...(model.devices.some(d=>d.rackId===r.id&&d.face==='rear')?['rear']:[])])
            content.push({ unbreakable: true, stack: [{ text: r.name + ' · ' + r.heightU + 'U · '+(face==='rear'?'Arka yüz':'Ön yüz'), style: 'heading' }, { svg: R.ReportOutput.rackSVG(model, r, face), width: Math.min(420, 580 * 480 / (r.heightU * 12 + 44)) }] });
        content.push({ text: 'Envanter', style: 'heading' }, grid(['Kimlik / kabin', 'Cihaz / model', 'Konum / seri / IP'], model.devices.map(d => [d.id + '\n' + d.rack, d.name + '\n' + d.model, 'U' + d.topU + ' · ' + d.face + '\n' + (d.serialNumber || 'Seri belirtilmedi') + '\n' + (d.ipAddress || 'IP belirtilmedi')]), [100, '*', 110]), { text: 'Bağlantılar', style: 'heading' }, grid(['Hat / tür / rol', 'Kaynak', 'Hedef', 'Tahmin / ölçüm / satın alma'], model.cables.map(c => [c.id + '\n' + c.name + '\n' + (c.medium || 'Ortam belirtilmedi') + ' / ' + (c.role || 'Rol belirtilmedi'), c.from.label, c.to.label, [c.estimated, c.measured, c.purchase].map(R.ReportOutput.meter).join('\n')]), [95, '*', '*', 85]), { text: 'Gözlemler', style: 'heading' }, grid(['Kimlik / kaynak / zaman', 'Nesne / gözlem'], doc.observations.map(o => [o.id + '\n' + (typeof o.source === 'string' ? o.source : o.source?.filename || o.source?.system || 'Belirtilmedi') + '\n' + (o.collectedAt || o.receivedAt || 'Tarih belirtilmedi'), (o.entityRef?.id || 'Eşleşmedi') + '\n' + JSON.stringify(o.normalized || o.raw || {})]), [170, '*']), { text: 'Açık işler', style: 'heading' }, grid(['Tür / kimlik', 'İş'], model.issues.map(i => [i.kind + '\n' + i.id, i.text]), [150, '*']), { text: 'Malzeme listesi', style: 'heading' }, grid(['Kalem', 'Adet', 'Birim fiyat / ara toplam', 'Kaynak kimlikler'], bom.rows.map(r => [r.name, r.quantity, (r.unitPrice ?? 'Girilmedi') + ' / ' + (r.totalPrice ?? 'Hesaplanmadı'), r.sourceIds.join(', ')]), ['*', 35, 95, 160]), { text: 'Fiyatlı kalemler ara toplamı: ' + bom.totalPrice + ' ' + bom.options.currency + ' · ' + bom.unpricedRows + ' fiyat eksik.\n' + bom.notes.join('\n'), fontSize: 8 }, grid(['Metraj', 'Bilinen toplam', 'Bilinen / bilinmeyen hat'], Object.entries(bom.totals).map(([k, v]) => [k, v.meters + ' m', v.known + ' / ' + v.unknown])), grid(['Bilinmeyen kalem', 'Kaynak / gerekçe'], bom.unknown.map(r => [r.name, r.sourceIds.join(', ') + ' · ' + r.reason])));
        return { pageSize: 'A4', pageMargins: [36, 46, 36, 42], defaultStyle: { font: 'Roboto', fontSize: 9 }, styles: { title: { fontSize: 20, bold: true, margin: [0, 0, 0, 8] }, heading: { fontSize: 13, bold: true, margin: [0, 12, 0, 6] } }, info: { title: doc.metadata.name || 'Proje raporu', subject: 'Dondurulmuş revizyon ' + doc.revision, creator: 'Rack Studio' }, header: { text: R.LabelModel.short((doc.metadata.name || 'Proje') + ' · revizyon ' + doc.revision, 85), margin: [36, 18, 36, 0], fontSize: 8 }, footer: (page, total) => ({ text: doc.projectId + ' · ' + page + ' / ' + total, alignment: 'center', fontSize: 7, margin: [0, 12, 0, 0] }), content };
    }
    function bytes(model, options) { return new Promise((resolve, reject) => { try {
        window.pdfMake.createPdf(definition(model, options)).getBuffer(buffer => resolve(new Uint8Array(buffer)));
    }
    catch (e) {
        reject(e);
    } }); }
    R.ReportPDF = Object.freeze({ definition, bytes });
})();
